  {"constraint": "飞船必须至少安装一对太阳能电池翼", "polarity": "must_have", "variants": [], "source": "common_sense"},
  {"constraint": "推进舱尾部必须可见推进喷口", "polarity": "must_have", "variants": [], "source": "common_sense"},
